import java.util.*;

class Solution {
    public int pivotIndex(int[] w) {
        int total = 0;
        for (int x : w) total += x;
        int left = 0;
        for (int i = 0; i < w.length; i++) {
            if (left == total - left - w[i]) return i; // left side equals right side
            left += w[i];
        }
        return -1;
    }
}

